values
  ('9f159beb-7117-4e09-a472-ea11507e75d5', 'a7b8c9d0-1e2f-4a15-8b45-5c6d7e8f9a75', null, 'topic'::public.curated_course_node_type, 'What Ancient Philosophy Is: Scope, Sources, and Method', 'This opening topic defines ancient philosophy as a historical, textual, and argumentative practice. Students learn how to read fragmentary evidence, dialogues, treatises, doxographies, and later reports without flattening them into modern textbook categories.', 0),
  ('a69dad4c-a3cf-40ef-a09d-fdfd3108a9e8', 'a7b8c9d0-1e2f-4a15-8b45-5c6d7e8f9a75', '9f159beb-7117-4e09-a472-ea11507e75d5', 'subtopic'::public.curated_course_node_type, 'Chronology and geography', 'The point is to orient students in the ancient Mediterranean world before they meet the arguments.', 0),
  ('a66e2da6-c16e-45f1-8681-a8d490e7dae8', 'a7b8c9d0-1e2f-4a15-8b45-5c6d7e8f9a75', 'a69dad4c-a3cf-40ef-a09d-fdfd3108a9e8', 'concept'::public.curated_course_node_type, 'Archaic, classical, Hellenistic, Roman, and late antique periods', null, 0),
