  ('478cf188-25cb-42ca-9cbf-bfa2c2881b12', 'a7b8c9d0-1e2f-4a15-8b45-5c6d7e8f9a75', null, 'topic'::public.curated_course_node_type, 'Greek Intellectual Context: Myth, Polis, Poetry, and Inquiry', 'Students situate philosophy inside archaic and classical Greek culture, including epic poetry, religion, civic life, rhetoric, medicine, mathematics, and the emerging practice of rational explanation.', 1),
