  ('02ed10b2-929e-4af5-980f-be5d8efab5c3', 'a7b8c9d0-1e2f-4a15-8b45-5c6d7e8f9a75', 'f0e79dd7-f04b-4dee-847e-e5b3e44bda69', 'concept'::public.curated_course_node_type, 'Elements, atoms, forms, and teleology', null, 0),
