select
  'history-of-ancient-philosophy',
  null,
  'History of Ancient Philosophy',
  'History of Ancient Philosophy',
  'History of Ancient Philosophy introduces students to major Greek and Roman philosophical texts, arguments, schools, and methods from early natural philosophy through late antique reception. Students learn to read primary texts closely, reconstruct arguments, interpret fragments and testimonia, compare translations, understand historical context, and evaluate enduring questions about nature, knowledge, virtue, soul, politics, science, and the good life.',
  $hanpjson${"slug": "history-of-ancient-philosophy", "title": "History of Ancient Philosophy", "description": "History of Ancient Philosophy introduces students to major Greek and Roman philosophical texts, arguments, schools, and methods from early natural philosophy through late antique reception. Students learn to read primary texts closely, reconstruct arguments, interpret fragments and testimonia, compare translations, understand historical context, and evaluate enduring questions about nature, knowledge, virtue, soul, politics, science, and the good life.", "topics": [{"id": "9f159beb-7117-4e09-a472-ea11507e75d5", "type": "topic", "title": "What Ancient Philosophy Is: Scope, Sources, and Method", "description": "This opening topic defines ancient philosophy as a historical, textual, and argumentative practice. Students learn how to read fragmentary evidence, dialogues, treatises, doxographies, and later reports without flattening them into modern textbook categories.", "children": [{"id": "a69dad4c-a3cf-40ef-a09d-fdfd3108a9e8", "type": "subtopic", "title": "Chronology and geography", "children": [{"id": "a66e2da6-c16e-45f1-8681-a8d490e7dae8", "type": "concept", "title": "Archaic, classical, Hellenistic, Roman, and late antique periods"}, {"id": "312c3e1c-83cc-4024-8d9e-0cc2ea84a8b7", "type": "concept", "title": "Ionia, Athens, Sicily, Alexandria, Rome, and imperial centers"}, {"id": "6241ab1e-3fa6-4f52-84db-281948f3a165", "type": "concept", "title": "Philosophy as a mobile practice across cities, schools, and languages"}], "description": "The point is to orient students in the ancient Mediterranean world before they meet the arguments."}, {"id": "38d77622-b457-419c-96c2-e48fa8f81342", "type": "subtopic", "title": "Kinds of evidence", "children": [{"id": "df2e5116-c9e8-4462-a599-ff918dc2f5ea", "type": "concept", "title": "Fragments and testimonia"}, {"id": "620c712e-ed0c-47fa-98d6-1d8f9c9ff7ae", "type": "concept", "title": "Dialogues, treatises, letters, speeches, and commentaries"}, {"id": "40192eda-a1c4-417c-b3c2-8a9996712185", "type": "concept", "title": "Doxography, biography, and later summaries"}], "description": "Ancient philosophy often survives through partial, mediated, or genre-specific sources."}, {"id": "7d1f8a30-d625-43bb-9269-51f1b5555a33", "type": "subtopic", "title": "Reading method", "children": [{"id": "0692f5fc-1bc4-4d36-a964-3260406a8920", "type": "concept", "title": "Close reading and argument reconstruction"}, {"id": "1be94242-fe97-4b96-b942-17fd0cfbebef", "type": "concept", "title": "Translation comparison and key Greek terms"}, {"id": "ca9e050c-6cd7-4098-8328-574a21933384", "type": "concept", "title": "Charity, context, and anachronism control"}], "description": "Students learn to interpret texts historically while still evaluating arguments philosophically."}]}, {"id": "478cf188-25cb-42ca-9cbf-bfa2c2881b12", "type": "topic", "title": "Greek Intellectual Context: Myth, Polis, Poetry, and Inquiry", "description": "Students situate philosophy inside archaic and classical Greek culture, including epic poetry, religion, civic life, rhetoric, medicine, mathematics, and the emerging practice of rational explanation.", "children": [{"id": "459d01ee-9a7c-4f91-be0e-d9a8be87142a", "type": "subtopic", "title": "Myth and rational explanation", "children": [{"id": "15b79574-3615-43ee-a5fe-b48b11a70090", "type": "concept", "title": "Homer, Hesiod, genealogy, and cosmogony"}, {"id": "c4164e74-1e86-4359-bcd4-3cbf3967bb8c", "type": "concept", "title": "Mythos and logos as overlapping modes"}, {"id": "c2fe0088-c64f-43d7-8e45-51097ce3d379", "type": "concept", "title": "The problem of origin, order, justice, and divine causality"}], "description": "Students learn that philosophy emerges from conversation with older poetic and religious forms, not from nowhere."}, {"id": "9e7f1a88-ee44-4d73-908e-f3f98fc9173e", "type": "subtopic", "title": "Polis and public reason", "children": [{"id": "a9c2850f-83cb-40e0-8821-7a1e95691fda", "type": "concept", "title": "Athenian democracy and public speech"}, {"id": "4edb48d0-a827-4af4-b6d9-4a4414a494dc", "type": "concept", "title": "Citizenship, slavery, gender, and exclusion"}, {"id": "2f0a8ffe-9477-42ed-844e-603c4aaaa06c", "type": "concept", "title": "The assembly, courts, symposium, and school"}], "description": "Philosophy develops in civic spaces shaped by law, debate, education, and conflict."}, {"id": "ae65d2f5-8b57-4f3e-a0b9-16fb81f3aa27", "type": "subtopic", "title": "Technical knowledge", "children": [{"id": "10cbef82-337c-49bc-8b1e-f2b4e2094088", "type": "concept", "title": "Hippocratic medicine and natural explanation"}, {"id": "a4ffb42b-6f31-4846-8fab-89028754244d", "type": "concept", "title": "Geometry and proof"}, {"id": "35d40840-148f-414c-a9f0-8069f899034c", "type": "concept", "title": "Rhetorical education and public persuasion"}], "description": "Ancient philosophy grows alongside medicine, mathematics, astronomy, and rhetoric."}]}, {"id": "4d855d86-1484-4df5-8f41-734b1c1e01d1", "type": "topic", "title": "Pre-Socratic Natural Philosophy", "description": "This topic examines early Greek attempts to explain nature, change, order, number, being, and knowledge before Socrates, with special attention to argument from sparse and mediated evidence.", "children": [{"id": "74552f97-62f9-4d06-be65-fab815100d1b", "type": "subtopic", "title": "Milesians and material principles", "children": [{"id": "41b4e88c-a571-44b7-ac2b-1da7c9b821d3", "type": "concept", "title": "Thales, Anaximander, and Anaximenes"}, {"id": "33b02e97-9750-46bd-b5ad-580cf6b6da93", "type": "concept", "title": "Arche, apeiron, air, and natural explanation"}, {"id": "cef57043-fe31-403d-a308-ce60d38f80d1", "type": "concept", "title": "Cosmology without mythic genealogy"}], "description": "Students examine early attempts to identify the basic stuff or principle of reality."}, {"id": "99e0e0ff-966e-4135-8ce0-3a2720328ca3", "type": "subtopic", "title": "Change, being, and plurality", "children": [{"id": "29ca74d3-7601-4ecf-b524-0cd842e9c900", "type": "concept", "title": "Heraclitus on flux and logos"}, {"id": "ea11c285-edf2-434f-9eaf-c6d960627559", "type": "concept", "title": "Parmenides on being and nonbeing"}, {"id": "f7363f48-77fe-49b6-ac6a-3a30a78681a8", "type": "concept", "title": "Empedocles, Anaxagoras, and pluralist responses"}], "description": "This subtopic introduces arguments that force later philosophers to clarify motion, identity, and explanation."}, {"id": "7391c771-a748-4074-94e5-206a3978aceb", "type": "subtopic", "title": "Number, atomism, and method", "children": [{"id": "ab2b281d-d624-4ccb-b07b-dc2e63fc5452", "type": "concept", "title": "Pythagorean number and harmony"}, {"id": "4badc6b9-7d25-4be0-9a89-02560faf65b5", "type": "concept", "title": "Leucippus and Democritus on atoms and void"}, {"id": "250328ad-7997-44da-b296-02583201a710", "type": "concept", "title": "Evidence, inference, and limits of reconstruction"}], "description": "Students see how abstraction, mathematics, and mechanism enter philosophical explanation."}]}, {"id": "dee2dae1-7f22-4528-8a6f-34c54b19df1b", "type": "topic", "title": "Sophists, Rhetoric, Relativism, and the Socratic Turn", "description": "Students study the shift from cosmology to human affairs: language, persuasion, virtue, education, law, convention, and Socrates' distinctive method of questioning.", "children": [{"id": "8f49473a-e831-48e0-a643-f1c8c648392f", "type": "subtopic", "title": "Sophistic education", "children": [{"id": "8d63b14b-b686-42cf-b4ba-49e6a3a5d9df", "type": "concept", "title": "Protagoras, Gorgias, Prodicus, and Hippias"}, {"id": "ae0fc5d4-b1ff-403c-810b-d2246d9567a8", "type": "concept", "title": "Nomos and physis"}, {"id": "015c1c48-8601-43ab-9725-b5a67a600b2a", "type": "concept", "title": "Paid teaching and cultural criticism"}], "description": "The Sophists force questions about expertise, virtue, language, and power."}, {"id": "570b8e5d-82df-4e80-843a-770253daed99", "type": "subtopic", "title": "Rhetoric and truth", "children": [{"id": "5fd5f02f-ffd7-469b-80ee-eddb5579e39d", "type": "concept", "title": "Gorgias on speech and power"}, {"id": "80b00ea2-4210-4e26-917d-888ffef2d5e7", "type": "concept", "title": "Eristic, rhetoric, and dialectic"}, {"id": "fc2a0792-bac0-4999-b5e5-ee9cb91593be", "type": "concept", "title": "Relativism, skepticism, and convention"}], "description": "Students learn why persuasion becomes philosophically urgent in democratic Athens."}, {"id": "08d8e4f8-1b1f-43de-8107-322a7899cbb6", "type": "subtopic", "title": "The Socratic turn", "children": [{"id": "5271d227-5061-444a-846a-e3f6022d0817", "type": "concept", "title": "What is courage, piety, justice, and virtue?"}, {"id": "24f7be1a-e35c-4818-b26a-15cd20d2e9f3", "type": "concept", "title": "Elenchus and aporia"}, {"id": "e46413bb-985e-4767-8432-cb5fe3f0ade5", "type": "concept", "title": "Care of the soul"}], "description": "This subtopic marks the move toward ethical examination and definitional inquiry."}]}, {"id": "7ead48bc-a0ba-4c5d-9231-f9bb3abf8331", "type": "topic", "title": "Socrates: Method, Ethics, Trial, and Philosophical Life", "description": "This topic treats Socrates as both a historical problem and a philosophical model, asking how examination, ignorance, virtue, and civic conflict become central to philosophy.", "children": [{"id": "ff24d304-60d9-4972-901b-4438dc39a927", "type": "subtopic", "title": "The Socratic problem", "children": [{"id": "029476f8-93e8-4079-b5dd-f79e452a58b4", "type": "concept", "title": "Plato, Xenophon, Aristophanes, and Aristotle"}, {"id": "a04fdca6-1ec1-411d-a192-855e4ddc9f68", "type": "concept", "title": "Historical Socrates versus literary Socrates"}, {"id": "0dd793ac-b7f3-4ae5-bec0-2e33663fdf5b", "type": "concept", "title": "Irony, character, and philosophical memory"}], "description": "Students learn why Socrates must be reconstructed through competing sources."}, {"id": "04d98c0f-10a8-44e5-9e6c-12bf49f05c9b", "type": "subtopic", "title": "Socratic ethics", "children": [{"id": "8e52e20a-c654-45b3-9332-d2bbecbb48c6", "type": "concept", "title": "No one errs willingly"}, {"id": "67501467-2dad-4e22-a880-55054f351ef7", "type": "concept", "title": "Virtue and knowledge"}, {"id": "8206fcce-f262-42c9-9c87-ed759b47bbde", "type": "concept", "title": "The examined life and moral seriousness"}], "description": "Socrates presents virtue as a matter of knowledge, examination, and psychic care."}, {"id": "9b9523b4-f089-490c-a150-268995431485", "type": "subtopic", "title": "Trial and civic conflict", "children": [{"id": "bf99453d-5034-4ecb-b5ca-2761a14abea4", "type": "concept", "title": "Apology, Crito, and Phaedo"}, {"id": "8c10ebab-b2bb-4dc5-98bc-4b6cc9029ef0", "type": "concept", "title": "Law, conscience, and civil disobedience"}, {"id": "2ac25a38-8aed-4f64-b443-47799d87515a", "type": "concept", "title": "Martyrdom, pedagogy, and philosophical identity"}], "description": "The trial shows philosophy's tension with democratic authority, piety, and public reputation."}]}, {"id": "6b2584cc-99f3-4aec-b3c9-94c02b4a2a7b", "type": "topic", "title": "Plato I: Dialogues, Forms, Knowledge, and Dialectic", "description": "Students learn Plato's literary and philosophical method through central epistemological and metaphysical arguments about knowledge, reality, recollection, and the Forms.", "children": [{"id": "7d83e6a9-d83a-4dc7-90d1-f046aacd7866", "type": "subtopic", "title": "Dialogue form", "children": [{"id": "089a86f6-f90a-45b6-8c6e-ec24605bdcd0", "type": "concept", "title": "Setting, speaker, irony, and dramatic action"}, {"id": "843b03a2-124b-4b37-94fd-4c8e491d1873", "type": "concept", "title": "Aporia and philosophical training"}, {"id": "808d72cf-944a-4a4f-9d12-38bb663df56c", "type": "concept", "title": "Myth, image, and argument"}], "description": "Students learn to read Plato as drama, argument, and pedagogy at once."}, {"id": "4a2331ee-94cb-45be-a343-50a4a6660861", "type": "subtopic", "title": "Knowledge and Forms", "children": [{"id": "8bed801e-e7ec-45c5-9d91-ad4be9f80cb3", "type": "concept", "title": "Meno, Phaedo, Republic, and Symposium"}, {"id": "db2ac9d3-cef4-409d-a054-06332b8ac44d", "type": "concept", "title": "Recollection, participation, and intelligibility"}, {"id": "306d58f8-6cbc-4952-8798-b6023ffc7264", "type": "concept", "title": "The divided line and cave"}], "description": "This is the core of Plato's metaphysics and epistemology."}, {"id": "c905d65b-39ca-453b-8e2f-09575df04818", "type": "subtopic", "title": "Dialectic", "children": [{"id": "d3b7229c-d234-43b0-a04f-19f70d50da38", "type": "concept", "title": "Definition and collection/division"}, {"id": "6697b928-d6c0-4802-9e6c-91f94af75c4d", "type": "concept", "title": "Hypothesis and first principles"}, {"id": "72082b9c-dfcb-4c44-ab3d-58ec5448da79", "type": "concept", "title": "The role of mathematics and education"}], "description": "Students study Plato's model of philosophical ascent and disciplined questioning."}]}, {"id": "9f1e80f0-3e6e-4c6a-9b24-92f7e659aadc", "type": "topic", "title": "Plato II: Soul, Ethics, Education, and Politics", "description": "This topic connects Plato's moral psychology to virtue, justice, education, eros, political order, and the risks of power and rhetoric.", "children": [{"id": "d0869125-65d7-4ffe-8f76-b842e67e4c76", "type": "subtopic", "title": "Moral psychology", "children": [{"id": "07156da1-bebd-43cb-8c0c-d376215dee27", "type": "concept", "title": "Tripartite soul"}, {"id": "410e62a3-64e4-4d41-8e80-b803b94875d1", "type": "concept", "title": "Reason, spirit, appetite, and psychic harmony"}, {"id": "10d27e43-ad13-48f0-b022-f63c798aea15", "type": "concept", "title": "Akrasia, eros, and philosophical transformation"}], "description": "Plato's ethics depends on a structured account of the soul and desire."}, {"id": "c714ee46-139e-48a6-b00e-e127672e412a", "type": "subtopic", "title": "Justice and the city", "children": [{"id": "c58d3b4f-5891-498d-8d42-f629b93b972a", "type": "concept", "title": "Republic on justice"}, {"id": "a63fc252-4b74-443a-88ed-1f65e73171b5", "type": "concept", "title": "Philosopher-rulers and education"}, {"id": "ea242cfd-bfc5-4020-962c-b022d59a537d", "type": "concept", "title": "Democracy, tyranny, and critique of power"}], "description": "Students connect personal virtue to political order and education."}, {"id": "901b899e-fdbd-481c-8b9d-d614bf0982e0", "type": "subtopic", "title": "Late Plato and law", "children": [{"id": "60feab62-c1f7-476a-92bf-814bb87c71df", "type": "concept", "title": "Statesman and Laws"}, {"id": "08cdf268-bd1d-42e1-bc54-9b6761df5980", "type": "concept", "title": "Rule of law and practical politics"}, {"id": "e7f34d46-fb59-4115-816d-7bdb5f56b2ee", "type": "concept", "title": "Tension between ideal theory and institutional design"}], "description": "The course broadens beyond the Republic to Plato's later reflections."}]}, {"id": "9ae40d20-2ac5-42a8-a342-d1e0a51eba81", "type": "topic", "title": "Aristotle I: Logic, Inquiry, Nature, and Science", "description": "Students examine Aristotle's tools for disciplined inquiry: categories, demonstration, explanation, causation, substance, biology, psychology, and the organization of knowledge.", "children": [{"id": "a6a7d4dc-7d51-430a-b822-aa5a0857cbde", "type": "subtopic", "title": "Logic and demonstration", "children": [{"id": "7e4cceb8-1039-4a27-b33a-0797812daa94", "type": "concept", "title": "Categories and propositions"}, {"id": "f80ebbbd-6ed5-4cb9-9453-9c42bc05e35c", "type": "concept", "title": "Syllogism and demonstration"}, {"id": "0bd0609a-685a-468f-be78-19a7ad1f0c0d", "type": "concept", "title": "Posterior Analytics and knowledge why"}], "description": "Students learn Aristotle's tools for validity, explanation, and scientific knowledge."}, {"id": "c6a81db5-ef54-474b-849b-95e46a69c512", "type": "subtopic", "title": "Four causes and natural inquiry", "children": [{"id": "a0ea8989-e32f-4d9a-9653-aeedf87f4485", "type": "concept", "title": "Material, formal, efficient, and final causes"}, {"id": "f0bf6a17-6b7c-45f1-a85b-abf079cc03ec", "type": "concept", "title": "Nature, motion, and teleology"}, {"id": "a9a95993-f509-41ed-968f-81abb2d5f69b", "type": "concept", "title": "Physics and biological explanation"}], "description": "Aristotle's science explains things through form, matter, agent, and end."}, {"id": "9f34607d-a316-4472-883a-3c71438e8115", "type": "subtopic", "title": "Soul and perception", "children": [{"id": "4343ed14-23cf-4922-95f6-48a0c950eba8", "type": "concept", "title": "Soul as form of a living body"}, {"id": "847d86c4-1450-4ce5-a2bd-6118066bf923", "type": "concept", "title": "Nutrition, perception, desire, and intellect"}, {"id": "b13fa717-a28b-43c8-a80a-93008d8f785b", "type": "concept", "title": "Continuities and differences between humans and animals"}], "description": "Students see Aristotle's psychology as a philosophy of living things."}]}, {"id": "4cd631e5-0c2e-42b9-8217-e23311342a13", "type": "topic", "title": "Aristotle II: Metaphysics, Soul, Ethics, and Politics", "description": "This topic studies Aristotle's account of being, form, actuality, soul, happiness, virtue, practical wisdom, friendship, citizenship, and the good life.", "children": [{"id": "695b01aa-73b2-4f41-9d0a-ed6cbbe1f81e", "type": "subtopic", "title": "Substance and being", "children": [{"id": "21585a89-d4b7-4748-b8a5-ad7940f3b4b0", "type": "concept", "title": "Substance, essence, form, and matter"}, {"id": "d3b65452-2c0f-4bd8-8c60-fd1b553a314f", "type": "concept", "title": "Potentiality and actuality"}, {"id": "05bc4fd2-6a5d-49f0-be34-2562f808c68e", "type": "concept", "title": "The unmoved mover and first philosophy"}], "description": "Students study Aristotle's most influential metaphysical vocabulary."}, {"id": "4a2f354d-204b-4a29-87e1-342ba54de7f1", "type": "subtopic", "title": "Virtue and happiness", "children": [{"id": "f8f224d6-012f-4fdb-bfb4-30e8421994e9", "type": "concept", "title": "Eudaimonia and function argument"}, {"id": "0a958b6a-cb73-4e68-8692-f7ae58b851e1", "type": "concept", "title": "Moral virtue, habit, and the mean"}, {"id": "d84d8517-4865-4c33-b7bc-11e90b3ecf45", "type": "concept", "title": "Practical wisdom, friendship, and contemplation"}], "description": "Aristotle's ethics asks what kind of life fulfills human nature."}, {"id": "19a5fa12-d4e1-40b7-acdc-39d4dd208696", "type": "subtopic", "title": "Politics and community", "children": [{"id": "98b157e1-c063-490e-9fcd-2021c5cf4810", "type": "concept", "title": "Humans as political animals"}, {"id": "e67eeb03-1e21-47ec-b74a-b32c94f53858", "type": "concept", "title": "Household, citizenship, and constitution"}, {"id": "6c943a2f-7bd7-451c-b96e-804cd0b0079f", "type": "concept", "title": "Justice, education, slavery, and exclusion"}], "description": "Aristotle treats ethics and politics as continuous inquiries into human flourishing."}]}, {"id": "07a24b57-6615-4622-b77a-f0b6c2cfca72", "type": "topic", "title": "Hellenistic Philosophy: Epicureans, Stoics, and Skeptics", "description": "Students learn how philosophy becomes a way of life after Aristotle, with competing accounts of nature, tranquility, virtue, emotion, fate, knowledge, and freedom.", "children": [{"id": "b4d6ca76-0167-4e5a-aa85-0c6a8211a124", "type": "subtopic", "title": "Epicureanism", "children": [{"id": "00553da7-3a6c-42b5-849a-bfe9f9c0d9a6", "type": "concept", "title": "Epicurus on pleasure and desire"}, {"id": "e001c95a-aa69-4d7c-9fb7-532350789da2", "type": "concept", "title": "Atoms, gods, death, and anxiety"}, {"id": "c972c6a0-4274-469f-b033-78c670782d68", "type": "concept", "title": "Community and the garden"}], "description": "Students learn an atomist ethics of pleasure, tranquility, friendship, and freedom from fear."}, {"id": "3c55c5a1-b239-4638-b896-cc8075c90835", "type": "subtopic", "title": "Stoicism", "children": [{"id": "f80402fc-5158-45d7-a925-a27b83eb89cc", "type": "concept", "title": "Logic, physics, and ethics"}, {"id": "7b535de4-7447-461c-990d-0739579843e6", "type": "concept", "title": "Living according to nature"}, {"id": "07435cd5-f857-4a4e-8b2b-1ac71115df7e", "type": "concept", "title": "Apatheia, oikeiosis, cosmopolitanism, and duty"}], "description": "Stoicism offers a systematic account of nature, reason, fate, virtue, and emotion."}, {"id": "d2d555a3-91b6-4e16-9637-6bbc14a70152", "type": "subtopic", "title": "Hellenistic philosophy as therapy", "children": [{"id": "e0317802-f177-4df6-a1ab-6e277661cec8", "type": "concept", "title": "Arguments as exercises"}, {"id": "3ecceae6-9532-44c8-9b8f-31d550a02681", "type": "concept", "title": "Passions, assent, and attention"}, {"id": "07a5c3c7-b01f-4900-b069-f253793cd615", "type": "concept", "title": "Competing models of the good life"}], "description": "Philosophy becomes a disciplined practice for reshaping judgment and life."}]}, {"id": "a11ca470-0951-44e6-ba8d-0e05a59a9170", "type": "topic", "title": "Ancient Skepticism, Pyrrhonism, and the Problem of Knowledge", "description": "This topic gives skepticism sustained attention, showing how ancient skeptics challenge dogmatism, suspend judgment, and reshape later epistemology.", "children": [{"id": "d125ef49-854c-43af-9bd7-89957625f18a", "type": "subtopic", "title": "Academic skepticism", "children": [{"id": "c5c2a07b-c3c7-42a6-a9eb-d9190857878f", "type": "concept", "title": "Arcesilaus and Carneades"}, {"id": "e2bad672-d94c-4d4a-ac1f-b85bb84b3c38", "type": "concept", "title": "Probability, plausibility, and practical action"}, {"id": "3d05a2ab-3d56-480a-952e-b4091035d3f1", "type": "concept", "title": "Critique of Stoic certainty"}], "description": "Students study the skeptical transformation of Plato's Academy."}, {"id": "ead99049-b6b4-4a44-981f-70f9398d05f9", "type": "subtopic", "title": "Pyrrhonism", "children": [{"id": "cefcf262-3409-456b-9c1c-cb5481ca2a4e", "type": "concept", "title": "Pyrrho, Aenesidemus, and Sextus Empiricus"}, {"id": "bcb5fea5-3840-4caa-b1e8-a94465c53651", "type": "concept", "title": "Modes of skepticism"}, {"id": "33b97cdb-f0e2-43bc-a3b2-dfb2d2d51f32", "type": "concept", "title": "Epoché and ataraxia"}], "description": "Pyrrhonists aim at suspension of judgment and tranquility through argumentative balance."}, {"id": "0cc3106c-e2d0-4d24-a113-afa09437f013", "type": "subtopic", "title": "Skepticism's legacy", "children": [{"id": "5cd61662-c547-4131-a975-9abf9db7da59", "type": "concept", "title": "Problem of the criterion"}, {"id": "53fb3b9c-1370-43af-ba92-e084763519d6", "type": "concept", "title": "Appearance and reality"}, {"id": "d831f238-8fb3-4447-a037-1e70d88f202c", "type": "concept", "title": "Influence on modern skepticism and scientific humility"}], "description": "Ancient skepticism remains a central source for later epistemology."}]}, {"id": "acb56c19-f6e6-4e39-bbd0-dad986fe352b", "type": "topic", "title": "Ancient Philosophy of Nature, Mathematics, Medicine, and Mind", "description": "Students see that ancient philosophy is not separated from science: theories of elements, causes, mathematics, perception, soul, body, medicine, and cosmology are central to its ambitions.", "children": [{"id": "f0e79dd7-f04b-4dee-847e-e5b3e44bda69", "type": "subtopic", "title": "Nature and cosmology", "children": [{"id": "02ed10b2-929e-4af5-980f-be5d8efab5c3", "type": "concept", "title": "Elements, atoms, forms, and teleology"}, {"id": "ae3f87fa-28c7-462a-aafc-b5344dc7463c", "type": "concept", "title": "Cosmos, necessity, chance, and providence"}, {"id": "1a1f07be-7593-4ee9-a67f-19ea24f5b19a", "type": "concept", "title": "Plato's Timaeus and Aristotle's Physics"}], "description": "Students connect metaphysics with ancient accounts of the cosmos and living order."}, {"id": "7771afbf-f157-4310-9240-a6e0be7ed967", "type": "subtopic", "title": "Mathematics and proof", "children": [{"id": "d8249713-2fdb-495c-ac2a-10f36d83c5db", "type": "concept", "title": "Pythagoreanism and mathematical order"}, {"id": "5ad31596-82e3-4fed-839f-a77e2b999099", "type": "concept", "title": "Geometry, demonstration, and abstraction"}, {"id": "6995c5d4-b799-4cd0-b85a-f2e01bde324e", "type": "concept", "title": "Plato, Aristotle, and mathematical objects"}], "description": "Ancient philosophy repeatedly turns to mathematics as a model of knowledge."}, {"id": "0f5edef0-6ba6-483e-a68c-31cd96177dbb", "type": "subtopic", "title": "Medicine, body, and soul", "children": [{"id": "a3627172-49d8-4dd3-b51f-afcb159b763d", "type": "concept", "title": "Hippocratic naturalism"}, {"id": "d1e4f65b-c356-4167-ac11-2c5d8a796648", "type": "concept", "title": "Perception, emotion, and cognition"}, {"id": "eda3e466-47ba-4750-baac-85874f072708", "type": "concept", "title": "Health, harmony, and care of the self"}], "description": "Students explore how theories of body and soul cross philosophy and medicine."}]}, {"id": "7ae25436-f435-4a00-b714-a7bd04aa602f", "type": "topic", "title": "Roman, Late Antique, and Neoplatonic Reception", "description": "This topic follows ancient philosophy into Roman, imperial, and late antique settings, showing how Cicero, Seneca, Epictetus, Marcus Aurelius, Plotinus, and commentators transmit and transform Greek philosophy.", "children": [{"id": "ddbb7114-8335-435b-b1a3-ab3dce964959", "type": "subtopic", "title": "Roman philosophical culture", "children": [{"id": "49b8f4e9-174e-4f3a-9d56-db10aac5a97b", "type": "concept", "title": "Cicero as mediator"}, {"id": "0646cd7b-b778-4717-832f-7bee2cdcf85e", "type": "concept", "title": "Lucretius and Epicurean poetry"}, {"id": "fba829d1-b2ba-460a-94bb-13fb32c10fcf", "type": "concept", "title": "Seneca, Epictetus, and Marcus Aurelius"}], "description": "Students learn how Greek philosophy is translated into Roman elite, political, and literary contexts."}, {"id": "2178ce21-ed14-4b4d-83ce-2fa8f1638930", "type": "subtopic", "title": "Commentary traditions", "children": [{"id": "dc9e5278-8981-4312-a76c-d63cf6fc180b", "type": "concept", "title": "Commentators on Aristotle"}, {"id": "04d949e4-4c50-4620-b4fd-25bd14ef46d5", "type": "concept", "title": "School organization and curriculum"}, {"id": "81d66d3e-2a48-4162-a68a-ea5cdf616248", "type": "concept", "title": "Doxography and system-building"}], "description": "Later philosophers preserve and reshape Plato and Aristotle through teaching and commentary."}, {"id": "22b7adac-5a26-4a78-9527-07ceadcb2a4a", "type": "subtopic", "title": "Neoplatonism", "children": [{"id": "6ce61b37-813a-4f62-ac32-82a8b87674a2", "type": "concept", "title": "The One, Intellect, and Soul"}, {"id": "e926951a-0ccd-4441-9f27-2d3287f9f5db", "type": "concept", "title": "Emanation and return"}, {"id": "da1767a1-63e6-4919-967d-61b89f1185dc", "type": "concept", "title": "Porphyry, Iamblichus, Proclus, and late antique philosophy"}], "description": "Plotinus and later Platonists transform ancient metaphysics and spiritual practice."}]}, {"id": "b2eafb93-20a5-46ef-b90b-aa0b2c02583b", "type": "topic", "title": "Transmission, Translation, Commentary, and Global Reception", "description": "Students learn how ancient texts survive, how translation shapes interpretation, and how Greek philosophy travels through Arabic, Latin, Jewish, Christian, Islamic, Renaissance, and modern contexts.", "children": [{"id": "3a68b8a0-915d-49ef-a2ab-f968587849c2", "type": "subtopic", "title": "Textual transmission", "children": [{"id": "81cf483e-b737-4442-980b-70151c840ac7", "type": "concept", "title": "Manuscripts, papyri, fragments, and scholia"}, {"id": "0f6ae5a5-5ccb-4c87-8baf-58ea432e68df", "type": "concept", "title": "Canon formation and lost works"}, {"id": "1c431a2d-bf94-4672-ac5e-ecd531364b77", "type": "concept", "title": "Critical editions and apparatuses"}], "description": "Students learn that ancient philosophy reaches us through fragile chains of copying, editing, and selection."}, {"id": "370a5418-359a-4641-8531-8bae90aa3b87", "type": "subtopic", "title": "Translation and interpretation", "children": [{"id": "f41428d3-89bc-433e-b2d3-0ecb4952e9c2", "type": "concept", "title": "Key Greek terms such as logos, arete, eudaimonia, psyche, ousia, physis, and nomos"}, {"id": "fae3af34-2ea4-4223-9f81-e126e789e07f", "type": "concept", "title": "Comparing translations"}, {"id": "3095d1f4-c87c-4ae5-9c1f-8f9c019f2c62", "type": "concept", "title": "Limits of one-word equivalents"}], "description": "Translation choices shape philosophical interpretation."}, {"id": "c2fdb08c-77a1-4c14-aaed-9c91a64daa44", "type": "subtopic", "title": "Global reception", "children": [{"id": "bd3e7cb4-c689-49f9-8b0f-896d98e7c803", "type": "concept", "title": "Arabic and Islamic transmission"}, {"id": "b971d703-357a-4198-a53e-bc30669e3f57", "type": "concept", "title": "Jewish and Christian engagements"}, {"id": "534d4584-fea3-45a5-9e45-ea82c43c35cd", "type": "concept", "title": "Renaissance, modern, and contemporary receptions"}], "description": "Ancient philosophy has multiple afterlives across languages and traditions."}]}, {"id": "cbce0331-4fea-4045-8d77-d038e54bec30", "type": "topic", "title": "Capstone Close Reading and Ancient Philosophy Research Paper", "description": "The capstone asks students to produce a careful interpretation of a primary text, connect it to scholarly debate, reconstruct arguments charitably, and defend an original thesis.", "children": [{"id": "97704551-6d5a-4114-874a-279274190c80", "type": "subtopic", "title": "Primary-text commentary", "children": [{"id": "10b938eb-8326-4dc9-817a-192d5a33228a", "type": "concept", "title": "Context, structure, and key terms"}, {"id": "27e11bb4-70d2-4195-b409-d61cd46086e1", "type": "concept", "title": "Argument reconstruction"}, {"id": "43d91515-0632-4fb1-a137-640eb5689e7a", "type": "concept", "title": "Interpretive alternatives"}], "description": "Students demonstrate that they can explain a passage line by line before arguing about it."}, {"id": "b32eb70b-0663-44d7-8798-415124e3c8e1", "type": "subtopic", "title": "Scholarly conversation", "children": [{"id": "d1ec2565-662b-4b19-8172-305d2cced233", "type": "concept", "title": "Finding secondary sources"}, {"id": "b0ec68d6-608c-49ac-8200-e8c28330a48c", "type": "concept", "title": "Literature review and citation"}, {"id": "7c3d1566-3da3-4505-bf7f-fc74c78b9895", "type": "concept", "title": "Agreement, objection, and contribution"}], "description": "The capstone teaches students to situate their claim among interpreters."}, {"id": "dd288799-2c03-4238-af9b-c4d22e0c3572", "type": "subtopic", "title": "Final seminar paper", "children": [{"id": "2d623b4f-5e64-4a11-86cf-7bfddb06718d", "type": "concept", "title": "Thesis, stakes, and roadmap"}, {"id": "37c46d3c-5710-4591-ad06-a9bbf9426596", "type": "concept", "title": "Objections and replies"}, {"id": "c65ee313-10f0-420e-bb4e-0964e39cc1be", "type": "concept", "title": "Revision, presentation, and oral defense"}], "description": "Students produce a polished philosophical-historical argument."}]}], "dbBacked": true}$hanpjson$::jsonb,
  true,
